-- YG-1617, YG-1620: İdari İşler Sorumlusu ve Müdürü ana ekranları.
ALTER TABLE idari_talep ADD COLUMN kategori text NOT NULL DEFAULT 'Genel' CHECK (kategori IN ('Genel', 'Bilgi Teknolojisi')), ADD COLUMN teknik_sart text, ADD COLUMN miktar numeric(12,2), ADD COLUMN bt_sartname text, ADD COLUMN satin_alma_zamani timestamptz, ADD COLUMN secilen_kart integer, ADD COLUMN teslim_plan date, ADD COLUMN teslim_zamani timestamptz, ADD COLUMN irsaliye_no text, ADD COLUMN fatura_no text, ADD COLUMN fatura_tutar_eur numeric(14,2), ADD COLUMN eslesme text CHECK (eslesme IN ('Eşleşti', 'Fark Var')), ADD COLUMN tedarikci_ref uuid;
ALTER TABLE idari_talep DROP CONSTRAINT IF EXISTS idari_talep_durum_check;
ALTER TABLE idari_talep ADD CONSTRAINT idari_talep_durum_check CHECK (durum IN ('İhtiyaç Onayında', 'İdari İşlerde', 'Müdürde', 'Sipariş Onayında', 'Sipariş Onaylandı', 'Teslim Alındı', 'Reddedildi', 'İade Edildi'));
CREATE TABLE idari_tedarikci (kimlik uuid PRIMARY KEY DEFAULT gen_random_uuid(), ad text NOT NULL UNIQUE, vergi_no text, iletisim text, iban text, iban_onayli boolean NOT NULL DEFAULT false, durum text NOT NULL DEFAULT 'Aktif' CHECK (durum IN ('Aktif', 'Pasif')), giren_ref text NOT NULL REFERENCES kullanici_hesabi (kimlik), zaman timestamptz NOT NULL DEFAULT now());
ALTER TABLE idari_talep ADD CONSTRAINT idari_talep_tedarikci_fk FOREIGN KEY (tedarikci_ref) REFERENCES idari_tedarikci (kimlik);
CREATE TABLE idari_fiyat_karti (kimlik bigserial PRIMARY KEY, talep_ref uuid NOT NULL REFERENCES idari_talep (kimlik), sira integer NOT NULL, tedarikci_ref uuid NOT NULL REFERENCES idari_tedarikci (kimlik), tutar_eur numeric(14,2) NOT NULL CHECK (tutar_eur > 0), gecerlilik date NOT NULL, belge_ref uuid, UNIQUE (talep_ref, sira));
ALTER TABLE varlik ADD COLUMN kritik_cihaz text CHECK (kritik_cihaz IN ('Nöbet Telefonu', 'İhbar Dizüstü')), ADD COLUMN ariza_zamani timestamptz, ADD COLUMN yedek_ref uuid REFERENCES varlik (kimlik);
ALTER TABLE varlik DROP CONSTRAINT IF EXISTS varlik_durum_check;
ALTER TABLE varlik ADD CONSTRAINT varlik_durum_check CHECK (durum IN ('Depoda', 'Zimmette', 'Arızalı', 'Hurda', 'Kayıp'));
CREATE TABLE varlik_sayim (kimlik bigserial PRIMARY KEY, donem text NOT NULL, varlik_ref uuid NOT NULL REFERENCES varlik (kimlik), sonuc text NOT NULL CHECK (sonuc IN ('Bulundu', 'Bulunamadı', 'Hasarlı')), sayan_ref text NOT NULL REFERENCES kullanici_hesabi (kimlik), zaman timestamptz NOT NULL DEFAULT now(), UNIQUE (donem, varlik_ref));
CREATE TABLE sarf_malzeme (kimlik uuid PRIMARY KEY DEFAULT gen_random_uuid(), ad text NOT NULL UNIQUE, birim text NOT NULL, miktar numeric(12,2) NOT NULL DEFAULT 0 CHECK (miktar >= 0), kritik_seviye numeric(12,2) NOT NULL DEFAULT 0);
CREATE TABLE sarf_hareket (kimlik bigserial PRIMARY KEY, malzeme_ref uuid NOT NULL REFERENCES sarf_malzeme (kimlik), tur text NOT NULL CHECK (tur IN ('Giriş', 'Çıkış', 'Sayım Düzeltmesi')), miktar numeric(12,2) NOT NULL, aciklama text, yapan_ref text NOT NULL REFERENCES kullanici_hesabi (kimlik), zaman timestamptz NOT NULL DEFAULT now());
CREATE TABLE ofis_sozlesmesi (kimlik uuid PRIMARY KEY DEFAULT gen_random_uuid(), sozlesme_no text NOT NULL UNIQUE CHECK (sozlesme_no ~ '^LGM-SZ-[0-9]{4}$'), karsi_taraf text NOT NULL, konu text NOT NULL, baslangic date NOT NULL, bitis date NOT NULL, yillik_tutar_eur numeric(14,2), durum text NOT NULL DEFAULT 'Yürürlükte' CHECK (durum IN ('Yürürlükte', 'Yenileme Önerildi', 'Fesih Önerildi', 'Yenilendi', 'Feshedildi', 'Sona Erdi')), oneri_gerekcesi text, giren_ref text NOT NULL REFERENCES kullanici_hesabi (kimlik), zaman timestamptz NOT NULL DEFAULT now());
CREATE TABLE idari_butce (kimlik uuid PRIMARY KEY DEFAULT gen_random_uuid(), yil integer NOT NULL, kalem text NOT NULL, tutar_eur numeric(14,2) NOT NULL CHECK (tutar_eur >= 0), durum text NOT NULL DEFAULT 'Taslak' CHECK (durum IN ('Taslak', 'TİD Onayında', 'Onaylandı', 'İade Edildi')), giren_ref text NOT NULL REFERENCES kullanici_hesabi (kimlik), UNIQUE (yil, kalem));
GRANT SELECT, INSERT, UPDATE ON idari_tedarikci, varlik_sayim, sarf_malzeme, ofis_sozlesmesi, idari_butce TO yatonet_uygulama; GRANT SELECT, INSERT, DELETE ON idari_fiyat_karti TO yatonet_uygulama; GRANT SELECT, INSERT ON sarf_hareket TO yatonet_uygulama;
GRANT USAGE ON SEQUENCE idari_fiyat_karti_kimlik_seq, varlik_sayim_kimlik_seq, sarf_hareket_kimlik_seq TO yatonet_uygulama;
